#include <stdio.h>
#define STR(x)  #x
#define TOSTR(x) STR(x)
#define VERSION 20260919
int main(void) {
    printf("STR(Hello World) = %s\n", STR(Hello World));
    printf("STR(a+b)         = %s\n", STR(a + b));
    printf("VERSION 直接展开  = %s\n", STR(VERSION));
    printf("VERSION 二次展开  = %s (用 TOSTR 让其先宏展开)\n", TOSTR(VERSION));
    return 0;
}
